{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C54"],
      "claim": "Tranexamic acid, a polar ionizable cyclohexanecarboxylic acid, has oral bioavailability of about 33-36% in humans, exceeding the 20% threshold despite low passive permeability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Gabapentin, a cyclohexaneacetic acid zwitterion, has absolute oral bioavailability of about 60% at a 300 mg dose in healthy volunteers, supporting high F for cyclohexane carboxylic acid-like structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Cilomilast, a cyclohexanecarboxylic acid derivative, is almost completely bioavailable (mean 96%) in humans, showing that carboxylic acid-containing cyclohexane compounds can have excellent oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Captopril, a small carboxylic acid drug, has an absolute oral bioavailability of about 60%, demonstrating that ionizable carboxylic acids can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Alpha-lipoic acid, a carboxylic acid with a cyclic disulfide, has approximately 30% oral bioavailability in humans, above the 20% threshold despite polarity and first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Biotin, a carboxylic acid with a bicyclic urea, has essentially 100% oral bioavailability in humans, indicating that polar carboxyl/urea-containing structures can be fully absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Phenoxymethylpenicillin, a beta-lactam carboxylic acid with multiple polar groups, has about 50% oral bioavailability in children, supporting F >=20% for polar carboxylic acid drugs.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Multiple high-transfer experimental analogues with carboxylic acid, cyclohexane, and zwitterionic features show oral bioavailability above 20% (tranexamic acid ~33%, gabapentin ~60%, cilomilast ~96%, captopril ~60%, alpha-lipoic acid ~30%, biotin ~100%, penicillin ~50%). The physicochemical prior predicts low permeability, but direct experimental evidence from structurally related ionizable acids outweighs it; therefore predict high (F >=20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "The query is more polar (logD -4.19, TPSA 124) than most supportive analogues, so the margin above 20% is uncertain.",
    "Potential active transport, efflux, and first-pass metabolism of the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

